  </script>
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --teal: #02838D;
      --teal-dark: #026a75;
      --charcoal: #231F20;
      --white: #FFFFFF;
      --warm-white: #FAFAFA;
      --light-gray: #F5F5F5;
      --mid-gray: #E0E0E0;
      --text-gray: #666666;
      --coral: #E07B54;
      --amber: #D4A853;
    }
    html { scroll-behavior: smooth; }
    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      color: var(--charcoal);
      background: var(--white);
      line-height: 1.6;
    }
    a { text-decoration: none; color: inherit; }
    img { max-width: 100%; display: block; }
    .container { max-width: 1200px; margin: 0 auto; padding: 0 20px; }

    /* Header & Nav */
    .header {
      background: var(--white);
      border-bottom: 1px solid var(--mid-gray);
      position: sticky;
      top: 0;
      z-index: 1000;
    }
    .header-top {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 16px 20px;
      max-width: 1200px;
      margin: 0 auto;
    }
    .logo {
      font-size: 28px;
      font-weight: 700;
      color: var(--teal);
      letter-spacing: -0.5px;
    }
    .logo span { color: var(--charcoal); }
    .header-actions {
      display: flex;
      gap: 20px;
      align-items: center;
    }
    .header-actions a {
      font-size: 14px;
      font-weight: 500;
      color: var(--charcoal);
    }
    .btn-subscribe {
      background: var(--coral);
      color: var(--white) !important;
      padding: 10px 20px;
      border-radius: 25px;
      font-weight: 600;
      transition: background 0.2s;
    }
    .btn-subscribe:hover { background: #c96a47; }

    .main-nav {
      background: var(--teal);
      padding: 0;
    }
    .nav-list {
      display: flex;
      list-style: none;
      max-width: 1200px;
      margin: 0 auto;
    }
    .nav-item {
      position: relative;
    }
    .nav-link {
      display: block;
      padding: 14px 20px;
      color: var(--white);
      font-size: 15px;
      font-weight: 500;
      cursor: pointer;
      transition: background 0.2s;
    }
    .nav-link:hover { background: rgba(255,255,255,0.1); }
    .nav-link::after {
      content: '▼';
      font-size: 8px;
      margin-left: 6px;
      vertical-align: middle;
      opacity: 0.7;
    }

    /* Mega Menu */
    .mega-menu {
      position: absolute;
      top: 100%;
      left: 0;
      background: var(--white);
      min-width: 800px;
      box-shadow: 0 10px 40px rgba(0,0,0,0.15);
      border-radius: 0 0 12px 12px;
      padding: 30px;
      display: none;
      z-index: 100;
    }
    .mega-menu.active { display: flex; gap: 40px; }
    .mega-menu-column { min-width: 180px; }
    .mega-menu-column h4 {
      font-size: 13px;
      font-weight: 700;
      color: var(--teal);
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin-bottom: 12px;
      padding-bottom: 8px;
      border-bottom: 2px solid var(--teal);
    }
    .mega-menu-column ul { list-style: none; }
    .mega-menu-column li { margin-bottom: 8px; }
    .mega-menu-column a {
      font-size: 14px;
      color: var(--charcoal);
      transition: color 0.2s;
    }
    .mega-menu-column a:hover { color: var(--teal); }

    /* Stats Ticker */
    .stats-ticker {
      background: linear-gradient(90deg, var(--teal), var(--teal-dark));
      padding: 12px 0;
      overflow: hidden;
    }
    .ticker-track {
      display: flex;
      animation: ticker 30s linear infinite;
      width: max-content;
    }
    .ticker-track:hover { animation-play-state: paused; }
    .ticker-item {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 0 40px;
      color: var(--white);
      font-size: 14px;
      font-weight: 500;
      white-space: nowrap;
    }
    .ticker-item .icon {
      width: 8px;
      height: 8px;
      background: var(--coral);
      border-radius: 50%;
    }
    @keyframes ticker {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }

    /* Hero */
    .hero {
      background: linear-gradient(135deg, var(--warm-white) 0%, var(--light-gray) 100%);
      padding: 60px 0;
    }
    .hero-content {
      display: grid;
      grid-template-columns: 1fr 400px;
      gap: 60px;
      align-items: center;
    }
    .hero-text .category {
      display: inline-block;
      background: var(--teal);
      color: var(--white);
      padding: 6px 14px;
      border-radius: 20px;
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin-bottom: 20px;
    }
    .hero-text h1 {
      font-size: 42px;
      font-weight: 700;
      line-height: 1.2;
      margin-bottom: 20px;
      color: var(--charcoal);
    }
    .hero-text p {
      font-size: 18px;
      color: var(--text-gray);
      margin-bottom: 30px;
      max-width: 540px;
    }
    .hero-cta {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      background: var(--charcoal);
      color: var(--white);
      padding: 14px 28px;
      border-radius: 30px;
      font-weight: 600;
      transition: background 0.2s;
    }
    .hero-cta:hover { background: #3a3637; }
    .hero-badge {
      background: var(--white);
      border-radius: 20px;
      padding: 40px;
      box-shadow: 0 10px 40px rgba(0,0,0,0.08);
      text-align: center;
    }
    .badge-title {
      font-size: 14px;
      font-weight: 700;
      color: var(--teal);
      text-transform: uppercase;
      letter-spacing: 1px;
      margin-bottom: 16px;
    }
    .badge-circle {
      width: 180px;
      height: 180px;
      border: 8px solid var(--teal);
      border-radius: 50%;
      margin: 0 auto 20px;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
    }
    .badge-number {
      font-size: 56px;
      font-weight: 700;
      color: var(--teal);
      line-height: 1;
    }
    .badge-label {
      font-size: 14px;
      font-weight: 600;
      color: var(--charcoal);
    }
    .badge-text {
      font-size: 14px;
      color: var(--text-gray);
    }

    /* Trending Sidebar */
    .trending-section {
      background: var(--white);
      padding: 60px 0;
    }
    .trending-grid {
      display: grid;
      grid-template-columns: 1fr 350px;
      gap: 60px;
    }
    .section-title {
      font-size: 28px;
      font-weight: 700;
      margin-bottom: 30px;
      color: var(--charcoal);
    }
    .article-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 30px;
    }
    .article-card {
      background: var(--warm-white);
      border-radius: 16px;
      overflow: hidden;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .article-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 10px 30px rgba(0,0,0,0.08);
    }
    .article-img {
      height: 160px;
      background: linear-gradient(135deg, var(--teal) 0%, #4aa5a9 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
      font-size: 48px;
      opacity: 0.3;
    }
    .article-body { padding: 20px; }
    .article-label {
      font-size: 11px;
      font-weight: 700;
      color: var(--coral);
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin-bottom: 8px;
    }
    .article-title {
      font-size: 16px;
      font-weight: 600;
      line-height: 1.4;
      color: var(--charcoal);
      margin-bottom: 8px;
    }
    .article-card:hover .article-title { color: var(--teal); }

    .trending-list {
      background: var(--light-gray);
      border-radius: 16px;
      padding: 30px;
    }
    .trending-list h3 {
      font-size: 20px;
      font-weight: 700;
      margin-bottom: 24px;
      color: var(--charcoal);
    }
    .trending-item {
      display: flex;
      gap: 16px;
      padding: 16px 0;
      border-bottom: 1px solid var(--mid-gray);
    }
    .trending-item:last-child { border-bottom: none; }
    .trending-num {
      font-size: 24px;
      font-weight: 700;
      color: var(--teal);
      opacity: 0.5;
      min-width: 30px;
    }
    .trending-item-content .label {
      font-size: 11px;
      font-weight: 700;
      color: var(--coral);
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin-bottom: 4px;
    }
    .trending-item-content .title {
      font-size: 14px;
      font-weight: 600;
      color: var(--charcoal);
      line-height: 1.4;
    }

    /* Newsletter CTA */
    .newsletter-cta {
      background: linear-gradient(135deg, var(--teal) 0%, var(--teal-dark) 100%);
      padding: 80px 0;
      text-align: center;
    }
    .newsletter-cta h2 {
      font-size: 36px;
      font-weight: 700;
      color: var(--white);
      margin-bottom: 16px;
    }
    .newsletter-cta p {
      font-size: 18px;
      color: rgba(255,255,255,0.9);
      margin-bottom: 30px;
      max-width: 500px;
      margin-left: auto;
      margin-right: auto;
    }
    .newsletter-form {
      display: flex;
      gap: 12px;
      max-width: 460px;
      margin: 0 auto 16px;
    }
    .newsletter-form input {
      flex: 1;
      padding: 16px 20px;
      border: none;
      border-radius: 30px;
      font-size: 16px;
      font-family: inherit;
    }
    .newsletter-form button {
      background: var(--coral);
      color: var(--white);
      border: none;
      padding: 16px 32px;
      border-radius: 30px;
      font-size: 16px;
      font-weight: 600;
      cursor: pointer;
      transition: background 0.2s;
    }
    .newsletter-form button:hover { background: #c96a47; }
    .newsletter-privacy {
      font-size: 13px;
      color: rgba(255,255,255,0.7);
    }

    /* Health Topics Carousel */
    .health-topics {
      padding: 60px 0;
      background: var(--warm-white);
    }
    .topics-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 30px;
    }
    .topics-header h2 { font-size: 28px; font-weight: 700; }
    .topics-header a {
      color: var(--teal);
      font-weight: 600;
      font-size: 15px;
    }
    .topics-carousel {
      display: flex;
      gap: 30px;
      overflow-x: auto;
      scroll-behavior: smooth;
      padding: 10px 0;
      -ms-overflow-style: none;
      scrollbar-width: none;
    }
    .topics-carousel::-webkit-scrollbar { display: none; }
    .topic-card {
      flex: 0 0 180px;
      text-align: center;
      cursor: pointer;
      transition: transform 0.2s;
    }
    .topic-card:hover { transform: scale(1.05); }
    .topic-icon {
      width: 140px;
      height: 140px;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--teal) 0%, #4aa5a9 100%);
      margin: 0 auto 16px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 48px;
      color: var(--white);
      box-shadow: 0 8px 24px rgba(2, 131, 141, 0.3);
    }
    .topic-card:nth-child(2) .topic-icon { background: linear-gradient(135deg, #6B8E23 0%, #9ACD32 100%); box-shadow: 0 8px 24px rgba(107, 142, 35, 0.3); }
    .topic-card:nth-child(3) .topic-icon { background: linear-gradient(135deg, #CD5C5C 0%, #F08080 100%); box-shadow: 0 8px 24px rgba(205, 92, 92, 0.3); }
    .topic-card:nth-child(4) .topic-icon { background: linear-gradient(135deg, #DA70D6 0%, #FFB6C1 100%); box-shadow: 0 8px 24px rgba(218, 112, 214, 0.3); }
    .topic-card:nth-child(5) .topic-icon { background: linear-gradient(135deg, #4169E1 0%, #6495ED 100%); box-shadow: 0 8px 24px rgba(65, 105, 225, 0.3); }
    .topic-card:nth-child(6) .topic-icon { background: linear-gradient(135deg, #FF8C00 0%, #FFA500 100%); box-shadow: 0 8px 24px rgba(255, 140, 0, 0.3); }
    .topic-name {
      font-size: 15px;
      font-weight: 600;
      color: var(--charcoal);
    }

    /* Health Tools */
    .health-tools {
      padding: 80px 0;
      background: var(--white);
    }
    .tools-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
    }
    .tools-column h3 {
      font-size: 24px;
      font-weight: 700;
      margin-bottom: 12px;
      color: var(--charcoal);
    }
    .tools-column > p {
      font-size: 16px;
      color: var(--text-gray);
      margin-bottom: 30px;
    }
    .tools-column .btn {
      display: inline-block;
      background: var(--teal);
      color: var(--white);
      padding: 12px 24px;
      border-radius: 25px;
      font-weight: 600;
      margin-bottom: 24px;
      transition: background 0.2s;
    }
    .tools-column .btn:hover { background: var(--teal-dark); }
    .tool-list { display: flex; flex-direction: column; gap: 16px; }
    .tool-item {
      display: flex;
      gap: 16px;
      padding: 20px;
      background: var(--warm-white);
      border-radius: 12px;
      transition: transform 0.2s;
    }
    .tool-item:hover { transform: translateX(4px); }
    .tool-icon {
      width: 48px;
      height: 48px;
      background: var(--light-gray);
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 20px;
      flex-shrink: 0;
    }
    .tool-item h4 {
      font-size: 16px;
      font-weight: 600;
      margin-bottom: 4px;
    }
    .tool-item p {
      font-size: 13px;
      color: var(--text-gray);
    }

    /* Recommended Reads */
    .recommended-reads {
      padding: 80px 0;
      background: var(--light-gray);
    }
    .tabs {
      display: flex;
      gap: 8px;
      margin-bottom: 40px;
      flex-wrap: wrap;
    }
    .tab {
      padding: 10px 20px;
      background: var(--white);
      border: none;
      border-radius: 25px;
      font-size: 14px;
      font-weight: 600;
      color: var(--charcoal);
      cursor: pointer;
      transition: all 0.2s;
      font-family: inherit;
    }
    .tab:hover { background: var(--mid-gray); }
    .tab.active {
      background: var(--teal);
      color: var(--white);
    }
    .reads-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 30px;
    }
    .read-card {
      background: var(--white);
      border-radius: 16px;
      overflow: hidden;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .read-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 10px 30px rgba(0,0,0,0.08);
    }
    .read-img {
      height: 180px;
      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
      font-size: 48px;
      opacity: 0.3;
    }
    .read-body { padding: 24px; }
    .read-title {
      font-size: 18px;
      font-weight: 600;
      line-height: 1.4;
      margin-bottom: 12px;
    }
    .read-card:hover .read-title { color: var(--teal); }

    /* Trust Section */
    .trust-section {
      padding: 80px 0;
      background: var(--white);
    }
    .trust-section h2 {
      font-size: 32px;
      font-weight: 700;
      text-align: center;
      margin-bottom: 50px;
      max-width: 600px;
      margin-left: auto;
      margin-right: auto;
    }
    .trust-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 40px;
    }
    .trust-card {
      text-align: center;
      padding: 30px 20px;
    }
    .trust-icon {
      width: 72px;
      height: 72px;
      background: var(--warm-white);
      border-radius: 50%;
      margin: 0 auto 20px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 32px;
    }
    .trust-card h4 {
      font-size: 18px;
      font-weight: 700;
      margin-bottom: 12px;
      color: var(--charcoal);
    }
    .trust-card p {
      font-size: 14px;
      color: var(--text-gray);
      line-height: 1.6;
    }

    /* Featured Programs */
    .featured-programs {
      padding: 80px 0;
      background: var(--warm-white);
    }
    .programs-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 30px;
    }
    .programs-header h2 { font-size: 28px; font-weight: 700; }
    .programs-header a {
      color: var(--teal);
      font-weight: 600;
      font-size: 15px;
    }
    .programs-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }
    .program-card {
      background: var(--white);
      border-radius: 16px;
      overflow: hidden;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .program-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 10px 30px rgba(0,0,0,0.08);
    }
    .program-img {
      height: 140px;
      background: linear-gradient(135deg, var(--teal) 0%, #4aa5a9 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
      font-size: 40px;
      opacity: 0.3;
    }
    .program-body { padding: 20px; }
    .program-title {
      font-size: 16px;
      font-weight: 600;
      color: var(--charcoal);
    }

    /* Latest Videos */
    .latest-videos {
      padding: 80px 0;
      background: var(--charcoal);
    }
    .latest-videos h2 {
      font-size: 28px;
      font-weight: 700;
      color: var(--white);
      margin-bottom: 30px;
    }
    .videos-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 30px;
    }
    .videos-header a {
      color: var(--teal);
      font-weight: 600;
      font-size: 15px;
    }
    .videos-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }
    .video-card {
      background: rgba(255,255,255,0.05);
      border-radius: 16px;
      overflow: hidden;
      transition: transform 0.2s;
    }
    .video-card:hover { transform: translateY(-4px); }
    .video-thumb {
      position: relative;
      height: 160px;
      background: linear-gradient(135deg, #1a1a1a 0%, #333 100%);
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .play-btn {
      width: 60px;
      height: 60px;
      background: var(--coral);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 24px;
      color: var(--white);
      padding-left: 4px;
    }
    .video-body { padding: 20px; }
    .video-title {
      font-size: 15px;
      font-weight: 600;
      color: var(--white);
      line-height: 1.4;
    }

    /* Footer */
    .footer {
      background: var(--white);
      padding: 60px 0 30px;
      border-top: 1px solid var(--mid-gray);
    }
    .footer-newsletter {
      text-align: center;
      margin-bottom: 50px;
    }
    .footer-newsletter h3 {
      font-size: 24px;
      font-weight: 700;
      margin-bottom: 16px;
    }
    .footer-newsletter p {
      color: var(--text-gray);
      margin-bottom: 24px;
      max-width: 500px;
      margin-left: auto;
      margin-right: auto;
    }
